head.script:
scwin.screenId = "jlddst37005";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst37005.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_request
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_request = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — null", unresolved: "action:null" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.request
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.request = async function () {
    /* sdd-asis-lifecycle:begin request — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.form1 || { elements: [] }).action = "null";
    (document.form1 || { elements: [] }).method = "post";
    await scwin.tx_request();
    /* sdd-asis-lifecycle:end */
};
